parameters.text:
=Please analyze the following incoming customer inquiry email and return the result strictly in the specified JSON schema.

[Sender]: {{ $json.from?.text || $json.from?.value?.[0]?.address || $json.from || '' }}
[Subject]: {{ $json.subject || '' }}
[Body]: {{ $json.text || $json.snippet || '' }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "description": "Category of inquiry: Billing, Technical, Account, or Other"
    },
    "priority": {
      "type": "string",
      "enum": ["High", "Medium", "Low"],
      "description": "Urgency level of the customer email"
    },
    "summary": {
      "type": "string",
      "description": "Concise summary of the inquiry within 1-2 sentences"
    },
    "reply_draft": {
      "type": "string",
      "description": "Professional and polite email reply draft"
    }
  },
  "required": [
    "category",
    "priority",
    "summary",
    "reply_draft"
  ]
}

parameters.jsCode:
const item = $input.first().json;
const gmail = $('When Email Arrives').first().json;

// Extract structured outputs from LangChain node
const priority = item.output?.priority || item.priority || 'Medium';
const category = item.output?.category || item.category || 'General Inquiry';
const summary = item.output?.summary || item.summary || '';
const replyDraft = item.output?.reply_draft || item.reply_draft || '';

// Robust extraction for sender and subject
const sender = 
  gmail.from?.text || 
  gmail.from?.value?.[0]?.address || 
  gmail.From || 
  gmail.from || 
  gmail.sender || 
  '';

const subject = 
  gmail.subject || 
  gmail.Subject || 
  'Customer Inquiry';

const threadId = gmail.threadId || gmail.thread_id || '';
const messageId = gmail.id || '';

const now = new Date();
let deadline = new Date(now);

// Dynamic SLA Logic
if (priority === 'High') {
  deadline.setHours(deadline.getHours() + 4);
} else if (priority === 'Medium') {
  deadline.setDate(deadline.getDate() + 1);
  deadline.setHours(18, 0, 0, 0);
} else {
  deadline.setDate(deadline.getDate() + 3);
  deadline.setHours(18, 0, 0, 0);
}

// Format local date string (JST)
const formatLocalDate = (date) => {
  const pad = (n) => String(n).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
};

return [{
  json: {
    priority: priority,
    category: category,
    summary: summary,
    replyDraft: replyDraft,
    sender: sender,
    subject: subject,
    threadId: threadId,
    messageId: messageId,
    startTime: now.toISOString(),
    deadlineTime: deadline.toISOString(),
    deadlineDisplay: formatLocalDate(deadline),
    taskTitle: `[Action Required / ${priority}] ${category}: ${subject}`
  }
}];

